    }
    // 如果 k 大于所有元素，不可能选出任何子序列
    if (k > maxA) {
        cout << 0 << "\n";
        return 0;
    }
    int M = max(maxA, k) + 1;
    vector<int> cnt(M, 0);
    for (int v : a) cnt[v]++;

    // 预处理2的幂次
    vector<long long> pow2(n + 1, 1);
    for (int i = 1; i <= n; i++) {
        pow2[i] = (pow2[i-1] * 2) % MOD;
    }

    // f[i] = i的倍数的个数
    vector<int> f(M, 0);
    for (int i = 1; i < M; i++) {
        for (int j = i; j < M; j += i) {
            f[i] += cnt[j];
        }
    }

    // g[i] = 2^{f[i]} - 1
    vector<long long> g(M, 0);
    for (int i = 1; i < M; i++) {
        g[i] = (pow2[f[i]] - 1 + MOD) % MOD;
    }

    // dp[i] = 核心值恰好为i的方案数
    vector<long long> dp(M, 0);
    for (int i = M - 1; i >= 1; i--) {
        dp[i] = g[i];
        for (int j = i * 2; j < M; j += i) {
            dp[i] = (dp[i] - dp[j] + MOD) % MOD;
        }
    }

    cout << dp[k] << "\n";
    return 0;
}
